455	    /**
456	     * Normalise a value for case-insensitive, whitespace-insensitive comparison:
457	     * trim, collapse internal runs of whitespace to a single space and lower-case.
458	     */
459	    private static String normalize(String value) {
460	        return OwnerDerivations.collapseWhitespace(value).toLowerCase();
461	    }
462	
463	    /**
464	     * Reduce an address to its canonical stored form. This is the value stored,
465	     * returned and used for every household comparison; see
466	     * {@link OwnerDerivations#normalizeAddress(String)} for the exact normalisation.
467	     *
468	     * @param value the raw address (may be {@code null})
469	     * @return the normalised address, or the empty string if {@code value} is
470	     *         {@code null} or blank
471	     */
472	    public static String normalizeAddress(String value) {
473	        return OwnerDerivations.normalizeAddress(value);
474	    }
475	
476	    protected Set<Pet> getPetsInternal() {
477	        if (this.pets == null) {
478	            this.pets = new HashSet<>();
479	        }
480	        return this.pets;
481	    }
482	
483	    protected void setPetsInternal(Set<Pet> pets) {
484	        this.pets = pets;
485	    }
486	
487	    public List<Pet> getPets() {
488	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
489	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
490	        return Collections.unmodifiableList(sortedPets);
491	    }
492	
493	    public void setPets(List<Pet> pets) {
494	        this.pets = new HashSet<>(pets);
495	    }
496	
497	    public void addPet(Pet pet) {
498	        getPetsInternal().add(pet);
499	        pet.setOwner(this);
500	    }
501	
502	    /**
503	     * Return the Pet with the given name, or null if none found for this Owner.
504	     *
505	     * @param name to test
506	     * @return true if pet name is already in use
507	     */
508	    public Pet getPet(String name) {
509	        return getPet(name, false);
510	    }
511	
512	    /**
513	     * Return the Pet with the given name, or null if none found for this Owner.
514	     *
515	     * @param name to test
516	     * @return true if pet name is already in use
517	     */
518	    public Pet getPet(String name, boolean ignoreNew) {
519	        name = name.toLowerCase();
520	        for (Pet pet : getPetsInternal()) {
521	            if (!ignoreNew || !pet.isNew()) {
522	                String compName = pet.getName();
523	                compName = compName.toLowerCase();
524	                if (compName.equals(name)) {
525	                    return pet;
526	                }
527	            }
528	        }
529	        return null;
530	    }
531	
532	    public Pet getPet(Integer petId) {
533	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
534	    }
535	
536	    @Override
537	    public String toString() {
538	        return new ToStringCreator(this)
539	
540	            .append("id", this.getId())
541	            .append("new", this.isNew())
542	            .append("lastName", this.getLastName())
543	            .append("firstName", this.getFirstName())
544	            .append("address", this.address)
545	            .append("city", this.city)
546	            .append("telephone", this.telephone)
547	            .toString();
548	    }
